import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.springframework.data.annotation.CreatedDate;
import org.springframework.data.jpa.domain.support.AuditingEntityListener;

@Entity
class CategoryEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;

    // TODO: chọn CascadeType/orphanRemoval cho quan hệ Category -> Product dựa trên
    // tiêu chí composition/aggregation đã nêu ở trên (so sánh với ví dụ Order -> OrderItem
    // đã giải đầy đủ bên dưới).
    @OneToMany(mappedBy = "category")
    private List<ProductEntity> products = new ArrayList<>();
}

@Entity
class ProductEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;
    private BigDecimal unitPrice;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "category_id", nullable = false)
    private CategoryEntity category;
}

@Entity
class UserEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String email;

    // TODO: chọn CascadeType/orphanRemoval cho quan hệ User -> Order dựa trên
    // tiêu chí composition/aggregation đã nêu ở trên.
    @OneToMany(mappedBy = "user")
    private List<OrderEntity> orders = new ArrayList<>();
}

@Entity
@EntityListeners(AuditingEntityListener.class)
class OrderEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id", nullable = false)
    private UserEntity user;

    @CreatedDate
    @Column(name = "created_at", updatable = false)
    private Instant createdAt;

    @OneToMany(mappedBy = "order", cascade = CascadeType.PERSIST, orphanRemoval = true)
    private List<OrderItemEntity> items = new ArrayList<>();
}

@Entity
class OrderItemEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id", nullable = false)
    private OrderEntity order;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_id", nullable = false)
    private ProductEntity product;

    private int quantity;
    private BigDecimal unitPriceAtOrder;
}

