import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.Query;
import java.time.Instant;

interface OrderRepository extends PagingAndSortingRepository<OrderEntity, Long> {

    @Query("select oi.product.id as productId, sum(oi.quantity) as totalQty "
         + "from OrderItemEntity oi group by oi.product.id order by totalQty desc")
    Page<ProductSalesProjection> topSellingProducts(Pageable pageable);

    Page<OrderEntity> findByCreatedAtBetween(Instant from, Instant to, Pageable pageable);

    Page<OrderEntity> findByUserId(Long userId, Pageable pageable);
}

